// Exnoria - exp.relationship.build
// Branch based on signal_id to handle different relationship scenarios
// This workflow executes AFTER HITL approval

const webhook = $("Webhook").first().json.body;
const contact = $input.first().json;

const { contact_id, signal_id, signal_severity, cause_code } = webhook;

const firstname = contact.properties?.firstname?.value ?? 'Contact';
const lastname  = contact.properties?.lastname?.value  ?? '';
const email     = contact.properties?.email?.value     ?? '';
const company   = contact.properties?.company?.value   ?? '';

let tags = [];
let taskSubject = null;
let taskPriority = 'HIGH';
let ownerId = null; // For assigning success manager

// Branch based on signal_id
if (signal_id === 'EXP_REL_01') {
  // Executive blockers - assign success manager
  tags.push('exp-relationship-active');
  taskSubject = `Executive relationship strategy for ${contact_id}`;
  // In production, this would set the account owner to a success manager
} else if (signal_id === 'EXP_REL_02') {
  // Lack of champions - create champion identification task
  tags.push('exp-champion-active');
  taskSubject = `Identify and activate internal champion at ${company || contact_id}`;
}

return [{
  json: {
    contact_id,
    signal_id,
    signal_severity,
    cause_code,
    email,
    firstname,
    lastname,
    company,
    tags,
    task_subject: taskSubject,
    task_priority: taskPriority,
    owner_id: ownerId
  }
}];
